"""In-process WebSocket fan-out for events generated by this edge server."""

import asyncio

from fastapi import WebSocket


class EventHub:
    """Track connected WebSocket clients and broadcast new event payloads."""

    def __init__(self) -> None:
        """Initialize the client set and lock protecting concurrent updates."""

        self._connections: set[WebSocket] = set()
        self._lock = asyncio.Lock()

    async def connect(self, websocket: WebSocket) -> None:
        """Accept a client connection and add it to the broadcast set."""

        await websocket.accept()
        async with self._lock:
            self._connections.add(websocket)

    async def disconnect(self, websocket: WebSocket) -> None:
        """Remove a disconnected client without failing if already absent."""

        async with self._lock:
            self._connections.discard(websocket)

    async def publish(self, payload: dict) -> None:
        """Send an event to all clients and discard connections that have gone stale."""

        async with self._lock:
            connections = list(self._connections)
        stale = []
        for connection in connections:
            try:
                await connection.send_json(payload)
            except (RuntimeError, OSError):
                stale.append(connection)
        if stale:
            async with self._lock:
                self._connections.difference_update(stale)


event_hub = EventHub()
